  my $opt = shift @ARGV;
  if ($opt eq '-x') { $mode = LOCK_EX }
  elsif ($opt eq '-s') { $mode = LOCK_SH }
  elsif ($opt eq '-n') { $nonblock = 1 }
  elsif ($opt eq '-w') { $wait = shift @ARGV }
  elsif ($opt eq '-E') { $conflict = shift @ARGV }
