my $deadline = defined $wait ? time + $wait : undef;
until (flock($fh, $mode | LOCK_NB)) {
  exit $conflict if $nonblock || (defined $deadline && time >= $deadline);
  sleep 0.01;
}
my @cmd = ($ARGV[0] // '') eq '-c' ? ('/bin/sh', '-c', $ARGV[1]) : @ARGV;
my $pid = fork();
if (!$pid) { exec @cmd or exit 127 }
waitpid($pid, 0);
exit($? >> 8);
